package cn.zhuatech.procureagent.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
/**
 * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
 */
@Service public class SourcingRecommendationApprovalService{/**
                                                             * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                             */
public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.requirementsApproved())b.add("采购需求与技术规格未批准");if(!r.bidderEligibilityVerified())b.add("供应商准入资格未验证");if(!r.conflictsDisclosedAndCleared())b.add("利益冲突未披露或未处理");if(!r.bidConfidentialityPreserved())b.add("投标保密与开标控制未满足");if(!r.sanctionsAndCompliancePassed())b.add("制裁与合规筛查未通过");if(!r.scoringEvidenceComplete())b.add("评分依据与评委记录不完整");if(!r.budgetConfirmed())b.add("采购预算未落实");if(!r.finalApprovalComplete())b.add("推荐授标审批未完成");if(!b.isEmpty()){a.add("阻断授标建议并完成合规、公平与预算整改");return new Assessment(Decision.BLOCKED,b,a);}if(r.priceVariancePercent()>r.maxPriceVariancePercent()||!r.contractingPlanReady()){if(r.priceVariancePercent()>r.maxPriceVariancePercent())a.add("启动价格偏差谈判和市场基准复核");if(!r.contractingPlanReady())a.add("准备合同条款、履约保证和签署计划");return new Assessment(Decision.NEGOTIATE,b,a);}a.add("批准推荐授标并锁定评分、报价、审批和模型版本");return new Assessment(Decision.AWARD,b,a);}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            */
public record Request(@NotBlank String sourcingEventId,boolean requirementsApproved,boolean bidderEligibilityVerified,boolean conflictsDisclosedAndCleared,boolean bidConfidentialityPreserved,boolean sanctionsAndCompliancePassed,boolean scoringEvidenceComplete,boolean budgetConfirmed,@DecimalMin("0")double priceVariancePercent,@DecimalMin("0")double maxPriceVariancePercent,boolean contractingPlanReady,boolean finalApprovalComplete){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                */
public record Assessment(Decision decision,List<String>blockers,List<String>actions){}/**
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      * 商业授权或定制开发请微信添加微信号zhuatech或zhuatech2进行咨询。
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      */
public enum Decision{AWARD,NEGOTIATE,BLOCKED}}
